package org.apache.commons.math.fraction;

import java.io.*;
import java.math.*;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.math.MathRuntimeException;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class Fraction_compareTo_TriageGen2Test {

    @Test
    public void testCompareTo_Less() {
        // nOd < dOn: 1/2 (0.5) < 3/4 (0.75) -> returns -1
        Fraction f1 = new Fraction(1, 2);
        Fraction f2 = new Fraction(3, 4);
        assertEquals(-1, f1.compareTo(f2));
    }

    @Test
    public void testCompareTo_Greater() {
        // nOd > dOn: 5/2 (2.5) > 1/1 (1.0) -> returns 1
        Fraction f1 = new Fraction(5, 2);
        Fraction f2 = new Fraction(1, 1);
        assertEquals(1, f1.compareTo(f2));
    }

    @Test
    public void testCompareTo_Equal() {
        // nOd == dOn: 1/2 (0.5) == 2/4 (0.5) -> returns 0
        Fraction f1 = new Fraction(1, 2);
        Fraction f2 = new Fraction(2, 4);
        assertEquals(0, f1.compareTo(f2));
    }

    @Test
    public void testCompareTo_NegativeValues() {
        // Testing negative logic: -1/2 (-0.5) < 1/2 (0.5) -> returns -1
        Fraction f1 = new Fraction(-1, 2);
        Fraction f2 = new Fraction(1, 2);
        assertEquals(-1, f1.compareTo(f2));

        // -1/2 (-0.5) > -3/4 (-0.75) -> returns 1
        Fraction f3 = new Fraction(-1, 2);
        Fraction f4 = new Fraction(-3, 4);
        assertEquals(1, f3.compareTo(f4));
    }

    @Test
    public void testCompareTo_Zero() {
        // 0/1 (0.0) == 0/5 (0.0) -> returns 0
        Fraction f1 = new Fraction(0, 1);
        Fraction f2 = new Fraction(0, 5);
        assertEquals(0, f1.compareTo(f2));

        // 0/1 (0.0) < 1/1 (1.0) -> returns -1
        Fraction f3 = new Fraction(0, 1);
        Fraction f4 = new Fraction(1, 1);
        assertEquals(-1, f3.compareTo(f4));
    }

    @Test
    public void testCompareTo_Precision() {
        // Testing very close values to ensure double comparison behavior
        Fraction f1 = new Fraction(1, 3); // 0.3333333333333333
        Fraction f2 = new Fraction(3333333333333333, 10000000000000000L); // Very close

        int result = f1.compareTo(f2);
        // Since the method uses doubleValue(), we are testing the double comparison logic
        // 1/3 as double is 0.3333333333333333148...
        // We just ensure the branch logic is covered.
        assertTrue(result == -1 || result == 0 || result == 1);
    }
}
